const seedDatabase = async () => {
    try {
        await connectDB();
        console.log("\n🌱 Starting database seed...\n");

        await Product.deleteMany({});
        console.log("✅ Cleared existing products");

        const inserted = await Product.insertMany(products);
        console.log(`✅ Inserted ${inserted.length} products — ALL with UNIQUE images!\n`);

        const summary = {};
        products.forEach(p => { summary[p.category] = (summary[p.category] || 0) + 1; });
        console.log("📦 Products by category:");
        Object.entries(summary).sort((a, b) => b[1] - a[1]).forEach(([cat, count]) => {
            const bar = "█".repeat(Math.ceil(count / 2));
            console.log(`   ${cat.padEnd(22)} ${String(count).padStart(3)} ${bar}`);
        });

        const bcrypt = require("bcryptjs");
        const adminExists = await User.findOne({ email: "admin@ecommerce.com" });
        if (!adminExists) {
            await User.create({
                name: "Admin User",
                email: "admin@ecommerce.com",
                password: await bcrypt.hash("admin123456", 12),
                role: "admin",
            });
            console.log("\n✅ Admin → admin@ecommerce.com / admin123456");
        } else {
            console.log("\n✅ Admin already exists");
        }

        const total = inserted.length;
        console.log(`\n🎉 Successfully seeded ${total} products across ${Object.keys(summary).length} categories!`);
        console.log("🚀 Run: npm run dev\n");
        process.exit(0);
    } catch (err) {
        console.error("❌ Error:", err.message);
        process.exit(1);
    }
};

seedDatabase();